1. Parse the JSON string into a Python object.
2. Recursively remove any `None` values from the object.
3. Count the frequency of all unique values in the processed object.
4. Replace all email addresses in the object with the string "None".
5. Return a dictionary containing the processed object and the value counts.

### code
```python
import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    def remove_none(obj):
        if obj is None:
            return None
        elif isinstance(obj, dict):
            return {k: remove_none(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [remove_none(item) for item in obj if item is not None]
        else:
            return obj
    def count_values(obj, counter):
        if isinstance(obj, dict):
            for v in obj.values():
                count_values(v, counter)
        elif isinstance(obj, list):
            for item in obj:
                count_values(item, counter)
        else:
            counter[obj] += 1
    def replace_email(obj):
        if isinstance(obj, dict):
            return {k: replace_email(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [replace_email(item) for item in obj]
        elif isinstance(obj, str):
            email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
            return re.sub(email_pattern, REPLACE_NONE, obj)
        else:
            return obj
    data = json.loads(json_str)
    cleaned = remove_none(data)
    value_counter = Counter()
    count_values(cleaned, value_counter)
    processed = replace_email(cleaned)
    return {"data": processed, "value_counts": value_counter}
